package com.m8trx.twin.history

import java.nio.file.Path
import java.time.Instant
import java.time.LocalDate

/**
 * One store-day of the RECENT window (Oct 2026 →), generated by exactly the machinery that wrote the history
 * files — `HistoryGenerator.plan` + `HistoryDayRunner.run` — so a day streamed live continues the year the
 * dashboards already show: same operating model, same story calendar, same seed derivation.
 *
 * The default seed is the history's own (`20261016`): `derive(seed, slug, date, "day")` is per store-day and
 * independent of the window, so the sales stream, the alarm drive and any re-run of the same date agree on
 * the same shoppers, the same baskets and the same gate crossings.
 *
 * Offline: no network, no credentials. The callers decide what (if anything) goes on the wire.
 */
class RecentDay(
    val seed: Long = HISTORY_SEED,
    chainDir: Path = Path.of("reference/data/chain"),
    modelPath: Path = Path.of("reference/data/store-operating-model.json"),
    keysPath: Path = ChainKeys.DEFAULT_PATH,
) {
    private val gen = HistoryGenerator(
        HistoryGenerator.Params(seed = seed, from = LocalDate.of(2026, 1, 1), to = LocalDate.of(2026, 1, 1), out = Path.of("out/recent-window")),
        chainDir,
        modelPath,
        keysPath,
    )
    private val chain = chainDir
    private val runners = HashMap<String, HistoryDayRunner>()

    val stores: List<ChainKeys.Store> get() = gen.keys.stores

    fun store(slug: String): ChainKeys.Store = gen.keys.store(slug)

    /** The store's local open instant on [date] (operating hours from the model). */
    fun openUtc(store: ChainKeys.Store, date: LocalDate): Instant =
        gen.closeUtc(store, date).minusSeconds(gen.model.store.operatingHours.openHours * 3600L)

    fun closeUtc(store: ChainKeys.Store, date: LocalDate): Instant = gen.closeUtc(store, date)

    fun isOpen(store: ChainKeys.Store, date: LocalDate): Boolean = gen.story.isOpen(store, date)

    /** Run one store-day. `null` when the story has the store closed that day (a holiday). */
    fun run(slug: String, date: LocalDate): Day? {
        val store = gen.keys.store(slug)
        if (!isOpen(store, date)) return null
        val runner = runners.getOrPut(slug) { HistoryDayRunner(store, gen.model, chain, gen.story::departmentWeights) }
        val plan = gen.plan(store, date)
        val r = runner.run(plan)
        val open = openUtc(store, date)
        val close = closeUtc(store, date)

        // A shopper who walks out a few seconds after close is stamped close − 1 s — the same clamp the history
        // applies to alarms, so no event of the day reads as after hours.
        fun clamp(t: Instant): Instant = if (t.isBefore(open)) {
            open
        } else if (!t.isBefore(close)) {
            close.minusSeconds(1)
        } else {
            t
        }
        return Day(
            slug = slug,
            date = date,
            open = open,
            close = close,
            txns = r.txns.map { it.copy(at = clamp(it.at)) }.sortedBy { it.at },
            alarms = r.alarms.map { it.copy(at = clamp(it.at)) }.sortedBy { it.at },
            visits = r.visits,
            units = r.units,
            cents = r.cents,
        )
    }

    class Day(
        val slug: String,
        val date: LocalDate,
        val open: Instant,
        val close: Instant,
        val txns: List<HistoryDayRunner.Txn>,
        val alarms: List<HistoryDayRunner.Alarm>,
        val visits: Int,
        val units: Int,
        val cents: Long,
    )

    companion object {
        /** The history files' seed — the recent window continues the same year. */
        const val HISTORY_SEED = 20261016L
    }
}
